public class OrderService {
  public bool Place(Order o) {
    if (o.Total <= 0) return false;
    return true;
  }
  public decimal Shipping(Order o) {
    return o.Total > 1000 ? 0m : 9.9m;
  }
  public void Cancel(Order o) { o.Status = "Cancelled"; }
}

